package com.grouphub.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtFilter extends OncePerRequestFilter {private final JwtService jwt;public JwtFilter(JwtService jwt){this.jwt=jwt;}@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)){String sub=jwt.subject(t);var a=new UsernamePasswordAuthenticationToken(sub,null,java.util.List.of(new SimpleGrantedAuthority("ROLE_ADMIN")));SecurityContextHolder.getContext().setAuthentication(a);}}chain.doFilter(req,res);}}
